<script setup lang="ts">
import { computed, ref } from 'vue'; import { Search } from 'lucide-vue-next'; import TaskTable from '../components/TaskTable.vue'; import { state } from '../stores/app'
const props=defineProps<{history?:boolean}>(); const q=ref(''); const kind=ref('all'); const status=ref('all'); const order=ref('newest'); const finished=['Completed','Failed','Cancelled']; const list=computed(()=>state.tasks.filter(task=>{ const belongsHere=props.history?finished.includes(task.status):!finished.includes(task.status); return belongsHere && (kind.value==='all'||task.mediaType===kind.value) && (status.value==='all'||task.status===status.value) && task.filename.toLowerCase().includes(q.value.toLowerCase()) }).sort((a,b)=>order.value==='newest'?new Date(b.createdAt).getTime()-new Date(a.createdAt).getTime():new Date(a.createdAt).getTime()-new Date(b.createdAt).getTime()))
</script>
<template><section class="page"><header class="page-head"><div><h1>{{history?'处理历史':'任务队列'}}</h1><p>{{history?'查看已完成、失败或取消的任务；成功任务可直接预览结果。':'仅显示等待中、处理中或已暂停的任务。完成、失败和取消的任务会自动移至处理历史。'}}</p></div></header><div class="filterbar panel"><label class="search"><Search :size="17"/><input v-model="q" placeholder="搜索文件名称"/></label><select v-model="kind"><option value="all">全部类型</option><option value="image">图片</option><option value="video">视频</option></select><select v-model="status"><option value="all">全部状态</option><template v-if="history"><option>Completed</option><option>Failed</option><option>Cancelled</option></template><template v-else><option>Waiting</option><option>Parsing</option><option>Processing</option><option>Paused</option></template></select><select v-if="history" v-model="order"><option value="newest">最新优先</option><option value="oldest">最早优先</option></select><span>{{list.length}} 个任务</span></div><article class="panel"><TaskTable :tasks="list"/></article></section></template>
